#!/usr/bin/env bash
# Simulate a 3-call session (2 approves + 1 swap) against forked Base state.
#
# Usage:
#   ./simulate-session.sh [API_URL] [SAVE]
#
#   API_URL  Base URL of the deployed app (default: http://localhost:3000)
#   SAVE     true/false — store the session for later restore via ?simulationId= (default: true)
#   RPC_URL  RPC endpoint to fork state from (default: http://172.26.172.16:9545)
set -euo pipefail

API_URL="${1:-http://localhost:3000}"
SAVE="${2:-true}"
RPC_URL="${3:-http://172.26.172.16:9545}"

cat <<JSON > /tmp/simulate-session-request.json
{
  "chainId": 8453,
  "blockNumber": "latest",
  "rpcUrl": "${RPC_URL}",
  "save": ${SAVE},
  "calls": [
    {
      "to": "0x11dC28D01984079b7efE7763b533e6ed9E3722B9",
      "data": "0x095ea7b3000000000000000000000000000000000022d473030f116ddee9f6b43ac78ba3ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",
      "value": "0x00",
      "from": "0x00eF17D98Ca5AcF523379CFdf006B739cCF46297"
    },
    {
      "to": "0x000000000022D473030F116dDEE9F6B43aC78BA3",
      "data": "0x87517c4500000000000000000000000011dc28d01984079b7efe7763b533e6ed9e3722b9000000000000000000000000fdf682f51fe81aa4898f0ae2163d8a55c127fbc7000000000000000000000000ffffffffffffffffffffffffffffffffffffffff000000000000000000000000000000000000000000000000000000006aa6a541",
      "value": "0x00",
      "from": "0x00eF17D98Ca5AcF523379CFdf006B739cCF46297"
    },
    {
      "to": "0xFdf682F51FE81Aa4898F0AE2163d8A55c127fbC7",
      "data": "",
      "value": "0x00",
      "from": "0x00eF17D98Ca5AcF523379CFdf006B739cCF46297"
    }
  ]
}
JSON

curl -sS -X POST "${API_URL%/}/api/simulate-tx" \
  -H "Content-Type: application/json" \
  -d @/tmp/simulate-session-request.json \
  -o /tmp/simulate-session-response.json

echo "Response saved to /tmp/simulate-session-response.json"
echo "Session results:"
python3 -c '
import json
with open("/tmp/simulate-session-response.json") as f:
    data = json.load(f)
for i, r in enumerate(data.get("results", []), 1):
    fn = (r.get("requestBody") or {}).get("functionName", "?")
    to = (r.get("requestBody") or {}).get("to", "?")
    status = "ok" if r.get("success") else f"FAILED: {r.get('error')}"
    print(f"  [{i}] {fn}({to}) gas={r.get('gasUsed')} {status}")
if data.get("simulationLink"):
    print("Restore link:", data["simulationLink"])
'